-- S-05: recurring incomes. Twin of S-04 (recurring expenses): a definition materializes one real incomes row per month
-- (fixed horizon, no scheduler). Every policy filters by (select public.current_household_id()) - see
-- context/foundation/lessons.md.
-- incomes gains a DELETE policy narrowed to rows generated by a definition (recurring_income_id is not null), so
-- stopping / re-generating can delete future entries. Manual rows stay delete-protected until S-06.
-- incomes has no category: the definition carries the same `source` (CHECK, 5 values) as the entries. Moving to a
-- category_id belongs to S-07, so there is deliberately no foreign key to categories here.
--
-- Rules are identical to S-04 (all dates in Europe/Warsaw, computed in the database; the helpers warsaw_today,
-- recurring_slot_date and recurring_month_diff come from 20261011130000_recurring_expenses.sql and are reused):
--   * slots run from start_month (the month the definition was created) to end_month, one row per month;
--   * a row's date is day_of_month clamped to the length of that month, computed from the base day for every month
--     (31 -> 31 Jan, 28 Feb, 31 Mar - no drift);
--   * "future" entries are rows dated after today; stop deletes them, an amount change deletes and re-creates them;
--   * the horizon covers at most 24 months counting the current one (months_left <= 23), for create and extend alike.

create table public.recurring_incomes (
  id uuid primary key default gen_random_uuid(),
  household_id uuid not null default public.current_household_id() references public.households (id) on delete cascade,
  source text not null check (source in ('wynagrodzenie', 'działalność', 'świadczenia', 'wynajem', 'inne')),
  amount_minor bigint not null check (amount_minor > 0 and amount_minor <= 9999999999),
  day_of_month smallint not null check (day_of_month between 1 and 31),
  start_month date not null check (extract(day from start_month) = 1),
  end_month date not null check (extract(day from end_month) = 1),
  stopped_at timestamptz,
  reminder_dismissed_at timestamptz,
  created_at timestamptz not null default now(),
  check (end_month >= start_month),
  -- Target of the composite foreign key on incomes.
  unique (household_id, id)
);

-- Two identical active definitions from the same month are almost certainly a double submit (two clicks, two tabs):
-- they would double the monthly totals, and stopping one would leave the other running. The API maps 23505 to a message.
create unique index recurring_incomes_active_unique_idx
  on public.recurring_incomes (household_id, source, amount_minor, day_of_month, start_month)
  where stopped_at is null;

alter table public.incomes add column recurring_income_id uuid;
-- Definitions are stopped (stopped_at), never deleted, so no ON DELETE action is needed. A null recurring_income_id
-- (a manual entry) skips the check (MATCH SIMPLE). Composite, so an entry cannot point at another household's definition.
alter table public.incomes
  add foreign key (household_id, recurring_income_id) references public.recurring_incomes (household_id, id);

create index incomes_recurring_income_idx on public.incomes (recurring_income_id, received_on)
  where recurring_income_id is not null;

alter table public.recurring_incomes enable row level security;

create policy "recurring_incomes_select_own" on public.recurring_incomes
  for select to authenticated
  using (household_id = (select public.current_household_id()));

create policy "recurring_incomes_insert_own" on public.recurring_incomes
  for insert to authenticated
  with check (household_id = (select public.current_household_id()));

create policy "recurring_incomes_update_own" on public.recurring_incomes
  for update to authenticated
  using (household_id = (select public.current_household_id()))
  with check (household_id = (select public.current_household_id()));

create policy "incomes_delete_generated" on public.incomes
  for delete to authenticated
  using (household_id = (select public.current_household_id()) and recurring_income_id is not null);

-- ===== Operations =====
-- All SECURITY INVOKER: household_id defaults to the caller's household and RLS scopes everything else. Each
-- operation is one transaction, so a failed regenerate never leaves a half-deleted horizon behind.
-- Operations on an existing definition lock its row (serializes two tabs / double clicks) and raise P0002 when it
-- does not exist for the caller, belongs to another household, or is stopped.

create function public.create_recurring_income(p_source text, p_amount_minor bigint, p_day int, p_months int)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_today date := public.warsaw_today();
  v_start date := v_today - (extract(day from v_today)::int - 1);
  v_id uuid;
begin
  if p_months is null or p_months not between 1 and 24 then
    raise exception 'p_months must be between 1 and 24' using errcode = '22023';
  end if;

  insert into public.recurring_incomes (source, amount_minor, day_of_month, start_month, end_month)
  values (p_source, p_amount_minor, p_day, v_start, (v_start + make_interval(months => p_months - 1))::date)
  returning id into v_id;

  insert into public.incomes (source, amount_minor, received_on, recurring_income_id)
  select p_source, p_amount_minor,
         public.recurring_slot_date((v_start + make_interval(months => g))::date, p_day), v_id
  from generate_series(0, p_months - 1) as g;

  return v_id;
end;
$$;

-- Deletes the future entries and re-creates them at the new amount: only slots dated after today, so entries dated
-- today or earlier keep their old amount.
create function public.update_recurring_income_amount(p_id uuid, p_amount_minor bigint)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_today date := public.warsaw_today();
  v_current date := v_today - (extract(day from v_today)::int - 1);
  v_def public.recurring_incomes;
begin
  select * into v_def from public.recurring_incomes where id = p_id and stopped_at is null for no key update;
  if not found then
    raise exception 'recurring income not found' using errcode = 'P0002';
  end if;

  update public.recurring_incomes set amount_minor = p_amount_minor where id = p_id;
  delete from public.incomes where recurring_income_id = p_id and received_on > v_today;

  insert into public.incomes (source, amount_minor, received_on, recurring_income_id)
  select v_def.source, p_amount_minor, s.received_on, p_id
  from (
    select public.recurring_slot_date((v_def.start_month + make_interval(months => g))::date, v_def.day_of_month) as received_on
    -- Slots before the current month are all dated before today, so the series starts at the current month.
    from generate_series(
      greatest(0, public.recurring_month_diff(v_def.start_month, v_current)),
      public.recurring_month_diff(v_def.start_month, v_def.end_month)
    ) as g
  ) s
  where s.received_on > v_today;
end;
$$;

-- Appends p_months slots after the horizon. A lapsed definition (end_month before the current month) restarts at the
-- current month, so nothing is created for past months. The horizon may cover at most 24 months counting the current one.
create function public.extend_recurring_income(p_id uuid, p_months int)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_today date := public.warsaw_today();
  v_current date := v_today - (extract(day from v_today)::int - 1);
  v_def public.recurring_incomes;
  v_first date;
  v_new_end date;
begin
  if p_months is null or p_months not between 1 and 24 then
    raise exception 'p_months must be between 1 and 24' using errcode = '22023';
  end if;

  select * into v_def from public.recurring_incomes where id = p_id and stopped_at is null for no key update;
  if not found then
    raise exception 'recurring income not found' using errcode = 'P0002';
  end if;

  v_first := greatest((v_def.end_month + make_interval(months => 1))::date, v_current);
  v_new_end := (v_first + make_interval(months => p_months - 1))::date;
  if public.recurring_month_diff(v_current, v_new_end) > 23 then
    raise exception 'the horizon cannot cover more than 24 months from the current one' using errcode = '22023';
  end if;

  update public.recurring_incomes set end_month = v_new_end, reminder_dismissed_at = null where id = p_id;

  insert into public.incomes (source, amount_minor, received_on, recurring_income_id)
  select v_def.source, v_def.amount_minor,
         public.recurring_slot_date((v_first + make_interval(months => g))::date, v_def.day_of_month), p_id
  from generate_series(0, p_months - 1) as g;
end;
$$;

-- Soft delete: the definition disappears from the list, the entries dated after today go, earlier ones stay.
create function public.stop_recurring_income(p_id uuid)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_today date := public.warsaw_today();
begin
  perform 1 from public.recurring_incomes where id = p_id and stopped_at is null for no key update;
  if not found then
    raise exception 'recurring income not found' using errcode = 'P0002';
  end if;

  delete from public.incomes where recurring_income_id = p_id and received_on > v_today;
  update public.recurring_incomes set stopped_at = now() where id = p_id;
end;
$$;

create function public.dismiss_recurring_income_reminder(p_id uuid)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
begin
  update public.recurring_incomes set reminder_dismissed_at = now() where id = p_id and stopped_at is null;
  if not found then
    raise exception 'recurring income not found' using errcode = 'P0002';
  end if;
end;
$$;

-- Active and lapsed definitions of the caller's household, newest first. months_left counts calendar months from the
-- current month to end_month (negative = lapsed); remind is true while 0 or 1 month is left and nobody dismissed it.
create function public.list_recurring_incomes()
returns table (
  id uuid,
  source text,
  amount_minor bigint,
  day_of_month int,
  start_month date,
  end_month date,
  months_left int,
  remind boolean
)
language sql
stable
security invoker
set search_path = ''
as $$
  select s.id, s.source, s.amount_minor, s.day_of_month, s.start_month, s.end_month, s.months_left,
         (s.reminder_dismissed_at is null and s.months_left between 0 and 1) as remind
  from (
    select r.id, r.source, r.amount_minor, r.day_of_month::int as day_of_month, r.start_month, r.end_month,
           r.created_at, r.reminder_dismissed_at,
           public.recurring_month_diff(public.warsaw_today(), r.end_month) as months_left
    from public.recurring_incomes r
    where r.stopped_at is null
  ) s
  order by s.created_at desc, s.id;
$$;

-- Supabase grants EXECUTE on new public functions to anon/authenticated (see 20261008200524_revoke_function_execute).
revoke execute on function public.create_recurring_income(text, bigint, int, int) from public, anon;
grant execute on function public.create_recurring_income(text, bigint, int, int) to authenticated;
revoke execute on function public.update_recurring_income_amount(uuid, bigint) from public, anon;
grant execute on function public.update_recurring_income_amount(uuid, bigint) to authenticated;
revoke execute on function public.extend_recurring_income(uuid, int) from public, anon;
grant execute on function public.extend_recurring_income(uuid, int) to authenticated;
revoke execute on function public.stop_recurring_income(uuid) from public, anon;
grant execute on function public.stop_recurring_income(uuid) to authenticated;
revoke execute on function public.dismiss_recurring_income_reminder(uuid) from public, anon;
grant execute on function public.dismiss_recurring_income_reminder(uuid) to authenticated;
revoke execute on function public.list_recurring_incomes() from public, anon;
grant execute on function public.list_recurring_incomes() to authenticated;
